from pathlib import Path
for name in ['package.json','compose.yaml','package_network.py','README.md','DEPLOY.md']:
 f=Path(name);f.write_text(f.read_text(encoding='utf-8-sig').replace('6.2.0','6.3.0'),encoding='utf-8')
f=Path('NETWORK.md');s=f.read_text(encoding='utf-8');s+='''\n\n## 6.3.0 — неподвижные круглые колодцы\n\nПри переносе узла или группы все физические колодцы вне группы сохраняют XY. Круглые колодцы не фиксируют направление трубы: угол в них свободно меняется. Прямоугольный колодец поворачивается к опорной прямой трубе, сохраняя выбранную стену и 90° выхода. По умолчанию опора — труба к круглому колодцу вне группы; при переносе группы приоритет у внутренней трубы, чтобы сохранить её форму. Опорная труба доступна в параметрах ориентации колодца. Свободные концы могут подстраиваться по нормали стены. При несовместимых неподвижных опорах перенос останавливается в последнем допустимом положении с названием узла, который нужно добавить в группу. Отметки и ручные вершины труб сохраняются. Это заменяет поведение 6.2, которое могло сдвигать соседний круглый колодец.\n''';f.write_text(s,encoding='utf-8')
